(function(){
  function scan(text){
    var lines=String(text||'').split(/\r?\n/), out=[];
    var pats=[
      ['AWS Key', /AKIA[0-9A-Z]{16}/],
      ['Private Key', /-----BEGIN (?:RSA |EC |OPENSSH |DSA |PGP )?PRIVATE KEY-----/],
      ['JWT', /eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/],
      ['Slack Token', /xox[baprs]-[0-9A-Za-z-]+/],
      ['Google API', /AIza[0-9A-Za-z_-]{35}/],
      ['GitHub Token', /gh[pousr]_[0-9A-Za-z]{36,}/],
      ['Stripe Key', /sk_live_[0-9A-Za-z]{24,}/],
      ['Password Assign', /(?:password|passwd|pwd|secret|api_key|apikey|token|access_key)\s*[:=]\s*['"][^'"]{3,}['"]/i],
      ['SSH Public', /ssh-(rsa|dss|ed25519|ecdsa-[a-z0-9]+)\s+[A-Za-z0-9+/]{20,}={0,2}/]
    ];
    for(var i=0;i<lines.length;i++){ for(var j=0;j<pats.length;j++){ if(pats[j][1].test(lines[i])){ out.push({n:i+1, type:pats[j][0], text:lines[i].trim()}); break; } } }
    return {value:out};
  }
  var API={scan:scan};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__GitleaksForge__=API;
})();
